#include "ark/agent.hpp"
#include "ark/sketch.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace ark;using V=arkjson::Value;
static void check(bool condition,const std::string& message){if(!condition)throw std::runtime_error(message);}
static V parse(const std::string& text){V result;check(arkjson::parse(text,result),"JSON fixture");return result;}
static V call(AgentSession& session,const char* name,V args){V result=session.call(name,args);check(!result.find("isError")->b,std::string(name)+": "+result.find("structuredContent")->dump());return *result.find("structuredContent");}
static void apply(AgentSession& session,V commands){V args=V::makeObj();args.set("commands",commands);args.set("expected_revision",V::makeNum(session.revision));call(session,"doc_apply",args);}
static V commandSketch(const std::string& name,V recipe){V entity=V::makeObj(),entities=V::makeArr(),sketch=V::makeObj(),command=V::makeObj();entity.set("kind",V::makeStr("recipe"));entity.set("name",V::makeStr("shape"));entity.set("recipe",recipe);entities.arr.push_back(entity);sketch.set("entities",entities);command.set("op",V::makeStr("sketch.set"));command.set("name",V::makeStr(name));command.set("sketch",sketch);return command;}
static void recipes(){
    for(const std::string& type:sketchRecipeTypes()){V recipe=sketchRecipeDefaults(type);std::string error;check(validateSketchEntityRecipe(recipe,error),type+": "+error);SketchEnt entity;entity.kind=SketchEnt::Recipe;entity.entityRecipe=recipe;evaluateSketchEntityRecipe(entity,ExprEnv{},.025);check(!entity.recipeSamples.empty(),type+": resolved samples");check(entity.entityRecipe.dump()==recipe.dump(),type+": authored recipe preserved");check(entity.recipeGeometry.t==V::Arr,type+": exact primitive DTO");for(auto& point:entity.recipeSamples)check(std::isfinite(point.x)&&std::isfinite(point.y),type+": finite samples");}
    SketchEnt ellipse;ellipse.kind=SketchEnt::Recipe;ellipse.entityRecipe=sketchRecipeDefaults("ellipse");evaluateSketchEntityRecipe(ellipse,ExprEnv{},.002);check(ellipse.recipeGeometry.arr.size()==4,"Ellipse emits four exact rational spans");for(const auto& span:ellipse.recipeGeometry.arr)check(std::abs(span.find("weights")->arr[1].num-std::sqrt(.5))<1e-10,"Ellipse rational quarter-circle weight");
    V rectangle=sketchRecipeDefaults("center_rectangle");rectangle.set("corner",parse(R"(["W/2",20])"));ExprEnv env;env.vars["W"]=60;SketchEnt driven;driven.kind=SketchEnt::Recipe;driven.entityRecipe=rectangle;evaluateSketchEntityRecipe(driven,env,.025);check(driven.dof[0]==-30&&driven.dof[2]==30,"Recipe dimensions evaluate named parameters");env.vars["W"]=80;evaluateSketchEntityRecipe(driven,env,.025);check(driven.dof[0]==-40,"Recipe expressions recompute");rectangle.set("mystery",V::makeNum(1));std::string error;check(!validateSketchEntityRecipe(rectangle,error),"Unknown recipe fields reject");
    V degenerate=sketchRecipeDefaults("straight_slot");degenerate.set("end",*degenerate.find("start"));driven.entityRecipe=degenerate;bool rejected=false;try{evaluateSketchEntityRecipe(driven,env,.025);}catch(...){rejected=true;}check(rejected,"Coincident slot centers reject");
    driven.entityRecipe=sketchRecipeDefaults("style_spline");driven.entityRecipe.set("controls",parse(R"([[5,5],[5,5],[5,5],[5,5]])"));rejected=false;try{evaluateSketchEntityRecipe(driven,env,.025);}catch(...){rejected=true;}check(rejected,"Zero-length style spline rejects during authoring without a native consumer");
    SketchEnt text;text.kind=SketchEnt::Recipe;text.entityRecipe=sketchRecipeDefaults("text");evaluateSketchEntityRecipe(text,env,.025);const auto paths=sampleSketchEntityPaths(text,.025);check(paths.size()==text.recipeGeometry.arr.size()&&paths.front().size()==2,"Text strokes remain separate display paths");
    AgentSession session;session.suppressIterationHistory();V commands=V::makeArr();commands.arr.push_back(commandSketch("Editable",sketchRecipeDefaults("ellipse")));apply(session,commands);const std::string saved=documentToJson(session.document,false,false);V document=parse(saved);check(document.find("version")->num==34,"Typed entity requires document version34");Document restored;check(documentFromJson(saved,restored,&error),"Recipe document roundtrip: "+error);auto* entity=&restored.findSketch("Editable")->sk.ents.front();check(entity->entityRecipe.find("type")->str=="ellipse"&&entity->recipeGeometry.t!=V::Arr,"Only authored source persists");
    const auto revision=session.revision;commands.arr[0]=commandSketch("Editable",degenerate);V args=V::makeObj();args.set("commands",commands);args.set("expected_revision",V::makeNum(revision));check(session.call("doc_apply",args).find("isError")->b&&session.revision==revision&&session.document.findSketch("Editable")->sk.ents.front().entityRecipe.find("type")->str=="ellipse","Invalid recipe leaves document and revision unchanged");
}
#ifdef ARK_SKETCH_ENTITIES_NATIVE_TESTS
static V report(AgentSession& session,u64 id){V args=V::makeObj();args.set("id",V::makeNum(id));return *call(session,"native_inspect",args).find("report");}
static void solids(){
    const std::pair<const char*,double> shapes[]={{"corner_rectangle",60*40*10},{"center_rectangle",60*40*10},{"three_point_rectangle",60*40*10},{"three_point_center_rectangle",60*40*10},{"parallelogram",60*40*10},{"straight_slot",(50*20+K_PI*100)*10},{"center_slot",(50*20+K_PI*100)*10},{"arc_slot",(40*deg2rad(120)*12+K_PI*36)*10},{"perimeter_circle",K_PI*900*10},{"ellipse",K_PI*40*20*10}};
    for(auto& fixture:shapes){AgentSession session;session.suppressIterationHistory();V commands=V::makeArr();commands.arr.push_back(commandSketch("Section",sketchRecipeDefaults(fixture.first)));commands.arr.push_back(parse(R"({"op":"feature.add","type":"native_solid","name":"Extrusion","native":{"op":"extrude"},"p":{"sketch":"Section","depth":10}})"));apply(session,commands);V evidence=report(session,1);check(std::abs(evidence.find("volume_mm3")->num-fixture.second)<.002,std::string(fixture.first)+": exact native volume");}
}
static void slotSweep(){
    AgentSession session;session.suppressIterationHistory();V commands=V::makeArr();
    const V recipe=sketchRecipeDefaults("straight_slot");commands.arr.push_back(commandSketch("Slot section",recipe));
    commands.arr.push_back(parse(R"({"op":"feature.add","type":"curve","name":"Slot path","native":{"start":[0,0,0],"segments":[{"kind":"line","to":[0,0,100]}]}})"));
    commands.arr.push_back(parse(R"({"op":"feature.add","type":"sweep","name":"Slot sweep","native":{"section":"Slot section","path":"Slot path"},"p":{"solid":1}})"));
    apply(session,commands);const V evidence=report(session,2);
    check(evidence.find("brep_valid")->b&&evidence.find("solids")->num==1,"Clockwise slot cap arcs form one valid swept solid");
    check(std::abs(evidence.find("volume_mm3")->num-(50*20+K_PI*100)*100)<.02,"Straight-slot sweep retains its exact section area and 100 mm path length");
    check(session.document.findSketch("Slot section")->sk.ents.front().entityRecipe.dump()==recipe.dump(),"Sweep retains the authored slot recipe");
}
static void spatial(){
    AgentSession constrained;constrained.suppressIterationHistory();apply(constrained,parse(R"JSON([{"op":"feature.add","type":"curve","name":"Constrained spline","native":{"start":[0,0,0],"segments":[{"kind":"spline","points":[[0,0,0],[15,5,40],[0,0,80]]}],"constraints":[{"id":"Start","type":"fixed","point":"start","value":[0,0,0]},{"id":"End","type":"fixed","point":"segment.1.point.3","value":[0,0,80]},{"id":"Middle","type":"fixed","point":"segment.1.point.2","value":[20,10,40]}]}}])JSON"));V solved=report(constrained,1);check(solved.find("spatial_constraints")->find("converged")->b&&constrained.document.find(1)->nativeSpec.find("segments")->arr[0].find("points")->arr[1].arr[0].num==15,"Native constrained spline solves handles while retaining authored point seeds");
    AgentSession session;session.suppressIterationHistory();apply(session,parse(R"JSON([
        {"op":"sketch.set","name":"Start","sketch":{"entities":[{"kind":"circle","dof":[0,0,10]}]}},
        {"op":"sketch.set","name":"Middle","sketch":{"entities":[{"kind":"circle","dof":[0,0,20]}]}},
        {"op":"sketch.set","name":"End","sketch":{"entities":[{"kind":"circle","dof":[0,0,30]}]}},
        {"op":"feature.add","type":"curve","name":"Spatial spline","native":{"start":[0,0,0],"segments":[{"kind":"spline","points":[[0,0,0],[0,0,50],[0,0,100]]}]}},
        {"op":"feature.add","type":"sweep","name":"Varying solid","native":{"path":"Spatial spline","sections":[{"section":"Start","fraction":0},{"section":"Middle","fraction":0.5},{"section":"End","fraction":1}]},"p":{"solid":1}}
    ])JSON"));V evidence=report(session,2);check(evidence.find("varying_sections")->num==3,"Three varying native section stations");check(evidence.find("dynamic_tangent_frames")->arr[1].find("origin")->arr[2].num==50,"Middle frame lies at exact path arc length");check(std::abs(evidence.find("volume_mm3")->num-K_PI*100*(100+300+900)/3)<.02,"Varying circular sections produce exact frustum volume");
    apply(session,parse(R"JSON([{"op":"feature.edit","id":1,"native":{"start":[0,0,0],"segments":[{"kind":"spline","points":[[0,0,0],[15,0,30],[10,10,65],[0,20,100]]}]}}])JSON"));evidence=report(session,2);check(evidence.find("volume_mm3")->num>0&&std::abs(evidence.find("dynamic_tangent_frames")->arr[1].find("normal")->arr[0].num)>.001,"Curved spline edit updates dynamic tangent section planes");
    AgentSession surface;surface.suppressIterationHistory();apply(surface,parse(R"JSON([{ "op":"feature.add","type":"bspline_surface","name":"Surface","native":{"poles":[[[0,0,0],[0,40,0]],[[40,0,0],[40,40,8]]]},"p":{"u_degree":1,"v_degree":1}},{"op":"feature.add","type":"curve","name":"UV spline","inputs":[1],"native":{"op":"surface_spline","controls":[[0.1,0.1],[0.3,0.8],[0.7,0.2],[0.9,0.9]]}}])JSON"));evidence=report(surface,2);check(evidence.find("surface_curve_authority")->str=="exact_UV_rational_Bezier_on_native_surface"&&evidence.find("length_mm")->num>30,"Native UV spline remains on the curved surface");
    const auto baseline=surface.revision;const std::string source=surface.document.find(2)->nativeSpec.dump();V invalid=V::makeObj(),edit=V::makeObj(),commands=V::makeArr(),arguments=V::makeObj();invalid=surface.document.find(2)->nativeSpec;invalid.set("constraints",parse(R"JSON([{"type":"fixed","point":"start","value":[0,0,0]}])JSON"));edit.set("op",V::makeStr("feature.edit"));edit.set("id",V::makeNum(2));edit.set("native",invalid);commands.arr.push_back(edit);arguments.set("commands",commands);arguments.set("expected_revision",V::makeNum(baseline));V rejection=surface.call("doc_apply",arguments);check(rejection.find("isError")->b&&surface.revision==baseline&&surface.document.find(2)->nativeSpec.dump()==source,"Unsupported constraints on a derived UV curve reject atomically");
    AgentSession equation;equation.suppressIterationHistory();apply(equation,parse(R"JSON([{"op":"feature.add","type":"curve","name":"Adaptive helix","native":{"op":"equation","x":"20*cos(t)","y":"20*sin(t)","z":"2*t","t0":0,"t1":"2*pi","samples":4}}])JSON"));evidence=report(equation,1);check(evidence.find("equation_refinements")->num>0&&evidence.find("equation_observed_max_error_mm")->num<=.01&&!evidence.find("equation_between_samples_bound_verified")->b,"Adaptive XYZ fit records measured accuracy without global proof");
    apply(equation,parse(R"JSON([{"op":"feature.add","type":"curve","name":"Exact polynomial","native":{"op":"equation","analytic":{"kind":"polynomial","x":[0,1],"y":[0,0,1],"z":[0]},"t0":0,"t1":2}},{"op":"feature.add","type":"curve","name":"Exact circle","native":{"op":"equation","analytic":{"kind":"circle","center":[0,0,0],"normal":[0,0,1],"x_axis":[1,0,0],"radius":20},"t0":0,"t1":"2*pi"}}])JSON"));evidence=report(equation,2);check(evidence.find("equation_authority")->str=="exact_analytic_polynomial"&&std::abs(evidence.find("length_mm")->num-(std::sqrt(17.)+.25*std::asinh(4.)))<1e-6,"Polynomial equation builds exact degree2 Bezier with analytic arc length");evidence=report(equation,3);check(evidence.find("equation_samples")->num==0&&std::abs(evidence.find("length_mm")->num-40*K_PI)<1e-7,"Typed circle equation has exact analytic authority without interpolation samples");
}
#endif
int main(){try{recipes();
#ifdef ARK_SKETCH_ENTITIES_NATIVE_TESTS
solids();slotSweep();spatial();
#endif
std::cout<<"Sketch entity recipes passed\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
